<?php
require_once 'config.php';require_role(['admin']);$pdo=db();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(($_POST['action']??'')==='account'){$name=trim($_POST['name']);if($name!==''){$q=$pdo->prepare("INSERT INTO accounts(name,description) VALUES(?,?)");$q->execute([$name,trim($_POST['description']??'')]);$msg='Compte ajouté.';}}elseif(($_POST['action']??'')==='category'){$acc=(int)($_POST['account_id']??0);$name=trim($_POST['category_name']??'');$kind=$_POST['kind']??'';$valid=$pdo->prepare('SELECT COUNT(*) FROM accounts WHERE id=?');$valid->execute([$acc]);if($name===''||!in_array($kind,['income','expense','both'],true)||(int)$valid->fetchColumn()===0)$msg='Compte, nom ou type de catégorie invalide.';else{$q=$pdo->prepare("INSERT INTO categories(account_id,name,kind) VALUES(?,?,?)");$q->execute([$acc,$name,$kind]);$msg='Catégorie ajoutée.';}}}
$accounts=$pdo->query("SELECT * FROM accounts ORDER BY id")->fetchAll();$cats=$pdo->query("SELECT c.*,a.name account_name FROM categories c LEFT JOIN accounts a ON a.id=c.account_id ORDER BY a.name,c.name")->fetchAll();$page_title='Comptes et catégories';include 'partials/header.php';?>
<?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif?><div class="grid two"><div class="panel"><h2>Créer un compte</h2><p>Ajoutez un compte financier supplémentaire selon les besoins de l'église.</p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="account"><label>Nom du compte</label><input name="name" required placeholder="Ex. Construction"><label>Description</label><textarea name="description" rows="3"></textarea><button class="btn primary">Ajouter le compte</button></form></div><div class="panel"><h2>Ajouter une catégorie</h2><p>Ex. carburant, entretien, transport, achat de matériel...</p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="category"><label>Compte concerné</label><select name="account_id"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['name'])?></option><?php endforeach?></select><label>Nom de la catégorie</label><input name="category_name" required><label>Utilisation</label><select name="kind"><option value="expense">Dépense</option><option value="income">Recette</option><option value="both">Les deux</option></select><button class="btn primary">Ajouter la catégorie</button></form></div></div>
<div class="panel"><h2>Comptes existants</h2><div class="table-wrap"><table><thead><tr><th>Compte</th><th>Description</th><th>Statut</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><?=h($a['name'])?></td><td><?=h($a['description'])?></td><td>Actif</td></tr><?php endforeach?></tbody></table></div></div>
<div class="panel"><h2>Catégories disponibles</h2><div class="table-wrap"><table><thead><tr><th>Compte</th><th>Catégorie</th><th>Type</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=h($c['account_name']??'Tous comptes')?></td><td><?=h($c['name'])?></td><td><?=h($c['kind'])?></td></tr><?php endforeach?></tbody></table></div></div><?php include 'partials/footer.php';?>
